function APR.farstrider:RequiresScenarioNavigation(step)
    local scenarioMapID = step and APR:GetScenarioMapIDForStep(step) or nil
    if not scenarioMapID then
        return false
    end

    local currentMapID = C_Map.GetBestMapForUnit("player")
    local parentMapID = APR:GetPlayerParentMapID()
    local isInsideScenario = currentMapID == scenarioMapID or parentMapID == scenarioMapID

    if step.LeaveScenario or step.LeaveInstance then
        return isInsideScenario
    end

    -- EnterScenario/EnterInstance steps guide the player to an exterior entrance; being
    -- outside is therefore the expected state. Any other step resolved to a registered
    -- scenario map requires the player to already be inside.
    if step.EnterScenario or step.EnterInstance then
        return false
    end

    return not isInsideScenario
end--[[APR_DIAG]]; APR.farstrider.RequiresScenarioNavigation = APRTrace("APR-Core/integrations/Farstrider.lua:55:APR.farstrider:RequiresScenarioNavigation#4", APR.farstrider.RequiresScenarioNavigation)--[[/APR_DIAG]]

function APR.farstrider:GetScenarioNavigationRequirement(step)
    if not step or step.EnterScenario or step.EnterInstance or step.LeaveScenario or step.LeaveInstance then
        return nil
    end

    local scenarioMapID = APR:GetScenarioMapIDForStep(step)
    local scenarioInfo = scenarioMapID and APR:GetScenarioZoneInfo(scenarioMapID) or nil
    local mapInfo = scenarioMapID and APR:GetMapInfoCached(scenarioMapID) or nil
    if not scenarioInfo or scenarioInfo.type ~= "DELVE" or not mapInfo or not mapInfo.name then
        return nil
    end

    return string.format(
        L["MUST_BE_IN_SCENARIO"],
        L[scenarioInfo.type],
        mapInfo.name
    )
end--[[APR_DIAG]]; APR.farstrider.GetScenarioNavigationRequirement = APRTrace("APR-Core/integrations/Farstrider.lua:79:APR.farstrider:GetScenarioNavigationRequirement#5", APR.farstrider.GetScenarioNavigationRequirement)--[[/APR_DIAG]]

function APR.farstrider:ShowScenarioEntranceFallback(step, destination, playerContext)
    if not self:RequiresScenarioNavigation(step) then
        return false
    end

    local scenarioMapID = APR:GetScenarioMapIDForStep(step)
    local scenarioInfo = scenarioMapID and APR:GetScenarioZoneInfo(scenarioMapID) or nil
    local entranceCoord = scenarioInfo and scenarioInfo.Coord or nil
    local entranceZone = scenarioInfo and scenarioInfo.zone or nil
    if not entranceCoord or not entranceZone then
        return false
    end

    local isInEntranceZone = false
    for _, mapID in ipairs(playerContext and playerContext.allRelevant or {}) do
        if mapID == entranceZone then
            isInEntranceZone = true
            break
        end
    end
    if not isInEntranceZone then
        return false
    end

    local mapInfo = APR:GetMapInfoCached(scenarioMapID)
    local instruction = string.format(
        L["ENTER_IN"],
        L[scenarioInfo.type],
        mapInfo and mapInfo.name or UNKNOWN
    )
    local entranceLocation = {
        mapId = entranceZone,
        pos = { x = entranceCoord.y, y = entranceCoord.x, z = entranceCoord.z or 0 },
        isUI = false,
    }
    local fallbackDestination = destination or {
        mapID = entranceZone,
        zone = entranceZone,
        worldCoord = entranceCoord,
    }

    return self:ShowPathStep({ {
        id = "scenario-entrance-" .. tostring(scenarioMapID),
        loc = entranceLocation,
        completionLoc = entranceLocation,
        loca = instruction,
        checkDistance = false,
        isScenarioEntranceFallback = true,
    } }, fallbackDestination)
end--[[APR_DIAG]]; APR.farstrider.ShowScenarioEntranceFallback = APRTrace("APR-Core/integrations/Farstrider.lua:98:APR.farstrider:ShowScenarioEntranceFallback#6", APR.farstrider.ShowScenarioEntranceFallback)--[[/APR_DIAG]]

local function GetFarstriderAPI()
    InstallSecretSafeFarstriderPredicates()
    if APR.foreverTravel then
        APR.foreverTravel:RefreshGraph()
    end

    local api = _G.FarstriderLib_API
    local missingDependencies = {}
    local hasFarstrider = type(api) == "table" and type(api.FindTrailTo) == "function"
    if not hasFarstrider then
        table.insert(missingDependencies, "FarstriderLib")
    end

    -- FarstriderLib exposes an empty data proxy when FarstriderLib Data is not
    -- loaded. A non-empty public WAYPOINTS table therefore detects the data
    -- package without pinning APR to one of its release numbers.
    local data
    if hasFarstrider then
        data = api.DATA
    else
        data = _G.FarstriderLibData_API
    end
    local hasFarstriderData = type(data) == "table" and
        type(data.WAYPOINTS) == "table" and next(data.WAYPOINTS) ~= nil
    if not hasFarstriderData then
        table.insert(missingDependencies, "FarstriderLibData")
    end

    if #missingDependencies > 0 then
        return nil, table.concat(missingDependencies, ", ")
    end

    return api
end--[[APR_DIAG]]; GetFarstriderAPI = APRTrace("APR-Core/integrations/Farstrider.lua:149:GetFarstriderAPI#7", GetFarstriderAPI)--[[/APR_DIAG]]

