function APR.farstrider:OnArrowUpdate(distance)
    local pathStep = self.activePathStep
    if not pathStep then
        return
    end

    local arrivalDistance = distance
    if pathStep.checkDistance then
        local completionX, completionY = FarstriderLocationToArrowPosition(pathStep.completionLoc)
        local playerY, playerX = UnitPosition("player")
        if not completionX or not playerY then
            return
        end

        local dx = playerX - completionX
        local dy = playerY - completionY
        arrivalDistance = math.sqrt(dx * dx + dy * dy)
    end

    if arrivalDistance > ARRIVAL_DISTANCE then
        return
    end

    local now = GetTime()
    if self._lastArrivalCheck and now - self._lastArrivalCheck < 1 then
        return
    end

    self._lastArrivalCheck = now
    self:InvalidatePathCache()
    self:ForceRefresh()
    self:GetMeToRightZone(true)
end--[[APR_DIAG]]; APR.farstrider.OnArrowUpdate = APRTrace("APR-Core/integrations/Farstrider.lua:460:APR.farstrider:OnArrowUpdate#27", APR.farstrider.OnArrowUpdate)--[[/APR_DIAG]]

function APR.farstrider:GetDestination(step, fallbackMapID)
    local preferredZone = APR:GetPreferredStepZone(step, fallbackMapID)
    if not preferredZone then
        return nil
    end

    local coord, coordZone = APR:GetStepCoord(step, fallbackMapID, preferredZone)
    local targetZone = coordZone or preferredZone
    if not coord then
        -- Zone-only steps (hearthstone, notes, some transport steps) still need
        -- a valid Farstrider goal. The zone centre lets the graph select the
        -- correct inter-map connection without restoring APR's old entry DB.
        return {
            mapID = targetZone,
            x = 0.5,
            y = 0.5,
            zone = targetZone,
        }
    end

    local uiMapID, x, y = WorldCoordToMapPosition(targetZone, coord)
    if not uiMapID then
        return {
            mapID = targetZone,
            x = 0.5,
            y = 0.5,
            zone = targetZone,
            worldCoord = coord,
        }
    end

    return {
        mapID = uiMapID,
        x = x,
        y = y,
        zone = targetZone,
        worldCoord = coord,
    }
end--[[APR_DIAG]]; APR.farstrider.GetDestination = APRTrace("APR-Core/integrations/Farstrider.lua:494:APR.farstrider:GetDestination#28", APR.farstrider.GetDestination)--[[/APR_DIAG]]

function APR.farstrider:ShowPathStep(path, destination)
    local pathStep = path and path[1] or nil
    if not pathStep or not pathStep.loc then
        return false
    end

    self.activePathStep = pathStep

    local action = SelectAction(pathStep.actionOptions)
    local instruction = pathStep.loca or L["PATH_NOT_FOUND"]

    if IsInInstance() and not action then
        instruction = L["LEAVE_INSTANCE"]
        APR.Arrow:SetArrowActive(false, 0, 0)
    else
        local arrowX, arrowY = FarstriderLocationToArrowPosition(pathStep.loc)
        if action then
            -- Action edges originate at the player's current position.
            APR.Arrow:SetArrowActive(false, 0, 0)
        elseif arrowX and arrowY then
            APR.Arrow:SetArrowActive(true, arrowX, arrowY)
        else
            self:ClearActivePath()
            return false
        end
    end

    local objectiveID = pathStep.id or destination.mapID
    APR.currentStep:AddQuestSteps(
        self.NavigationStepKey,
        instruction,
        objectiveID,
        nil,
        true,
        false
    )

    if action then
        APR.currentStep:AddStepButton(
            self.NavigationStepKey .. "-" .. tostring(objectiveID),
            action.data,
            action.type
        )
    end

    APR.currentStep:AddQuestDivider(self.NavigationDividerStepKey)
    return true
end--[[APR_DIAG]]; APR.farstrider.ShowPathStep = APRTrace("APR-Core/integrations/Farstrider.lua:534:APR.farstrider:ShowPathStep#29", APR.farstrider.ShowPathStep)--[[/APR_DIAG]]

function APR.farstrider:ShowPathError(destination, detail)
    local mapInfo = destination and APR:GetMapInfoCached(destination.zone or destination.mapID) or nil
    local destinationName = mapInfo and mapInfo.name or UNKNOWN
    local suffix = detail and (" (" .. detail .. ")") or ""

    APR.currentStep:AddQuestSteps(
        self.ErrorStepKey,
        string.format(L["ERROR_MESSAGE"], L["PATH_NOT_FOUND"] .. " " .. destinationName .. suffix),
        destination and destination.mapID or 0,
        nil,
        true,
        false,
        self.ErrorTextColor
    )
    APR.currentStep:AddQuestDivider(self.NavigationDividerStepKey)
    APR.Arrow:SetArrowActive(false, 0, 0)
end--[[APR_DIAG]]; APR.farstrider.ShowPathError = APRTrace("APR-Core/integrations/Farstrider.lua:583:APR.farstrider:ShowPathError#30", APR.farstrider.ShowPathError)--[[/APR_DIAG]]

local function RouteToRightZone(self, isRetry, preparedContext)
    APR:Debug("Function: APR.farstrider:GetMeToRightZone()", isRetry and "(retry)" or "")

    local now = GetTime()
    if not self._routingThrottle then
        self._routingThrottle = { count = 0, firstCall = now, lastCall = 0 }
    end

    local throttle = self._routingThrottle
    if now - throttle.lastCall < 0.3 then
        return
    end

    if now - throttle.firstCall > 3 then
        throttle.count = 0
        throttle.firstCall = now
    end

    throttle.count = throttle.count + 1
    throttle.lastCall = now
    if throttle.count > 15 and not self._routingForceRefresh then
        return
    end
    self._routingForceRefresh = nil

    -- This pass replaces any deferred check. Suppress checks requested by its own render.
    if self._stepCheckTimer then
        self._stepCheckTimer:Cancel()
        self._stepCheckTimer = nil
    end

    local playerMapID = C_Map.GetBestMapForUnit("player")
    if not playerMapID then
        APR:Debug("Farstrider: map API not ready")
        return
    end

    local contextProfileStart = APR:StartPerformanceSample()
    local playerContext = APR:ResolvePlayerZoneContext()
    APR:FinishPerformanceSample("ZoneRoutingContext", contextProfileStart)
    if not playerContext.allRelevant or #playerContext.allRelevant == 0 then
        APR:Debug("Farstrider: player zone context is not ready")
        return
    end

    local routeZoneMapIDs, fallbackMapID, routeName = APR:GetCurrentRouteMapIDsAndName()
    if routeZoneMapIDs and fallbackMapID and routeName then
        APR:ActivateRoute(routeName)
        if not APR.currentStep:IsShown() then
            APR.currentStep:RefreshCurrentStepFrameAnchor()
        end
    end

    if not APR.ActiveRoute or not APR.routeconfig:HasRouteInCustomPath() then
        APR.routeconfig:CheckIsCustomPathEmpty()
        return
    end

    if not APR:IsInstanceWithUI() or
        (not APRCustomPath[APR.PlayerID] and not APR:IsTemporaryRouteActive()) then
        return
    end

    local questProfileStart = APR:StartPerformanceSample()
    if preparedContext and APR:IsStepContextCurrent(preparedContext) and
        APR:IsStepContextCurrent(APR.lastRenderedStepContext) then
        APR:FinishPerformanceSample("ZoneRoutingReuseStep", questProfileStart)
    else
        APR:UpdateQuestAndStep()
    end
    APR:FinishPerformanceSample("ZoneRoutingQuestSync", questProfileStart)
    -- A long sequence of completed steps yields to the next frame. Route only its final step.
    if APR.stepUpdatePending or APR.stepUpdateTimer then return end
    self._scheduledStepContext = APR:CaptureStepContext()
    self._routedStepContext = self._scheduledStepContext
    self._scheduledStepToken = APR:GetCurrentStepToken(
        self._scheduledStepContext.route, self._scheduledStepContext.index)
    local step = APR:GetCurrentStep()
    if not step then
        return
    end

    -- An owned book can be used anywhere. Do not route a location-free item
    -- reminder back to the route's default map when it interrupts travel.
    if step.UseItem and not step.UseItem.questID and not step.Coord and not step.Coords
        and not step.Zone and not step.Zones then
        self:MarkRouteReady()
        return
    end

    -- The route was selected from this exact delve scenario. Do not ask Farstrider to
    -- navigate to the exterior Zone stored on delve steps while the player is inside it.
    if APR:IsInDelveRouteContext(APR.ActiveRoute) then
        self:MarkRouteReady()
        return
    end

    local destination = self:GetDestination(step, fallbackMapID)
    local farAway = false
    if destination and destination.worldCoord then
        local playerY, playerX = UnitPosition("player")
        if playerY and playerX then
            local dx = playerX - destination.worldCoord.x
            local dy = playerY - destination.worldCoord.y
            farAway = math.sqrt(dx * dx + dy * dy) >= APR.Arrow.MaxDistanceWrongZone
        end
    end

    local requiresScenarioNavigation = self:RequiresScenarioNavigation(step)
    local zoneProfileStart = APR:StartPerformanceSample()
    local isInRouteZone = APR:CheckIsInRouteZone()
    APR:FinishPerformanceSample("ZoneRoutingZoneCheck", zoneProfileStart)
    local api, missingDependencies = GetFarstriderAPI()
    local pathCallOk = false
    local optimizedPath
    if api and destination then
        local stepIndex = APRData[APR.PlayerID] and APRData[APR.PlayerID][APR.ActiveRoute]
        local cacheKey = string.format("%s|%s|%s|%s|%s|%s|%.5f|%.5f",
            tostring(playerMapID), tostring(APR.ActiveRoute), tostring(step._index or stepIndex),
            tostring(APR.stepRevision or 0),
            tostring(APR.RouteQuestStepList and APR.RouteQuestStepList[APR.ActiveRoute]),
            tostring(destination.mapID), destination.x or 0, destination.y or 0)
        local pathCache = self._pathCache
        if pathCache and pathCache.key == cacheKey and now < pathCache.expires then
            pathCallOk, optimizedPath = true, pathCache.path
        else
            local pathProfileStart = APR:StartPerformanceSample()
            pathCallOk, optimizedPath = --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](
                api.FindTrailTo,
                destination.mapID,
                destination.x,
                destination.y,
                0
            )
            APR:FinishPerformanceSample("FarstriderFindTrailTo", pathProfileStart)
            if pathCallOk then
                self._pathCache = {
                    key = cacheKey,
                    path = optimizedPath,
                    expires = GetTime() + PATH_CACHE_TTL,
                }
            else
                self:InvalidatePathCache()
                APR:Debug("FarstriderLib FindTrailTo failed:", optimizedPath)
            end
        end
    end

    local needsNavigation = not isInRouteZone or farAway or requiresScenarioNavigation or
        (pathCallOk and PathRequiresTravelAction(optimizedPath))
    if not needsNavigation then
        self:MarkRouteReady()
        return
    end

    APR.IsInRouteZone = false
    local wasShowingNavigation = self.showOutOfZoneStepContent
    self.showOutOfZoneStepContent = true
    self:ClearNavigationUiLines()
    self:ClearActivePath()

    if not wasShowingNavigation then
        APR.currentStep:RemoveQuestStepsAndExtraLineTexts()
        if APR.fillersFrame and APR.fillersFrame.RemoveFillerSteps then
            APR.fillersFrame:RemoveFillerSteps()
        end
    end

    if not destination then
        if not wasShowingNavigation then
            self:RefreshStepForNavigation()
        end
        self:ShowPathError(nil, L["PATH_ERROR_DESTINATION_MISSING"])
        return
    end

    if not isRetry and not self._retryPending then
        self._retryPending = true
        C_Timer.After(ROUTING_RETRY_DELAY, --[[APR_DIAG]]APRTrace("APR-Core/integrations/Farstrider.lua:779:callback#32", --[[/APR_DIAG]]function()
            self._retryPending = false
            if APR.IsInRouteZone or self:IsNavigating() or not APR.ActiveRoute then
                return
            end

            APR:InvalidatePlayerZoneCache()
            APR._lastRouteZoneCheck = nil
            APR._lastRouteZoneResult = nil
            self:ForceRefresh()
            self:GetMeToRightZone(true)
        end--[[APR_DIAG]])--[[/APR_DIAG]])
    end

    local targetMapInfo = APR:GetMapInfoCached(destination.zone)
    local parentMapInfo = targetMapInfo and targetMapInfo.parentMapID and
        APR:GetMapInfoCached(targetMapInfo.parentMapID) or nil
    local reason = requiresScenarioNavigation and self:GetScenarioNavigationRequirement(step) or nil
    reason = reason or (farAway and L["TOO_FAR_AWAY"] or L["WRONG_ZONE"])
    local destinationText = string.format(
        L["TRANSPORT_DESTINATION_ERROR"],
        reason,
        targetMapInfo and targetMapInfo.name or UNKNOWN,
        parentMapInfo and parentMapInfo.name or UNKNOWN,
        tostring(destination.zone)
    )
    APR.currentStep:AddExtraLineText(
        self.ErrorDestinationLineKey,
        destinationText,
        self.ErrorTextColor,
        false
    )

    if not wasShowingNavigation then
        self:RefreshStepForNavigation()
    end

    APR.Arrow:SetArrowActive(false, 0, 0)

    -- FarstriderData does not carry scenario entrance nodes. When the player is
    -- already in the recorded exterior zone, use APR's authoritative world
    -- coordinate directly instead of showing a path-not-found error.
    if self:ShowScenarioEntranceFallback(step, destination, playerContext) then
        return
    end

    if not api then
        ReportMissingDependencies(missingDependencies)
        self:ShowPathError(
            destination,
            string.format(L["PATH_ERROR_DEPENDENCY_MISSING"], missingDependencies)
        )
        return
    end

    if not pathCallOk then
        self:ShowPathError(destination, L["PATH_ERROR_ROUTING_FAILED"])
        return
    end

    if not optimizedPath or #optimizedPath == 0 or not self:ShowPathStep(optimizedPath, destination) then
        self:ShowPathError(destination)
    end
end--[[APR_DIAG]]; RouteToRightZone = APRTrace("APR-Core/integrations/Farstrider.lua:601:RouteToRightZone#31", RouteToRightZone)--[[/APR_DIAG]]

function APR.farstrider:GetMeToRightZone(isRetry, preparedContext)
    -- Never run pathfinding inside a current-step transaction or recursively from route messages.
    if self._routingInProgress then return end
    if APR.stepUpdateRunning or APR.stepUpdatePending or APR.stepUpdateTimer then
        self:RequestRouteCheck()
        return
    end
